script:
document.addEventListener('DOMContentLoaded', function () {
  const isOS2Theme = <%= @is_os2_theme == true ? 'true' : 'false' %>;
  const scriptTagExists = <%= @script_tag_exists == true ? 'true' : 'false' %>;
  const appConfigured = <%= @app_configured == true ? 'true' : 'false' %>;

  let activeInterval = null;
  let backgroundTimeout = null;
  let isChecking = false; // Prevent concurrent requests
  let monitoringActive = false; // Flag to track if monitoring should be active
  let completionToastShown = false; // Track if completion toast was already shown
  let embedStatus = <%= @appembedenabledornot ?'true' : 'false' %>;
  let blockStatus = <%= @appblockexistsornot ?'true' : 'false' %>;


  window.openEditor = (shop, uid, step, param) => {
    window.open(`https://${shop}/admin/themes/current/editor${param}=${uid}/${step === 'step1' ? 'app-embed' : 'app-block'}${step === 'step2' ? '&target=newAppsSection' : ''}`);
    startActiveMonitoring();
  };

  function updateStep(step, enabled) {
    const config = step === 'step1' ? { tone: 'info', text: 'Enabled' } : { tone: 'warning', text: 'Added' };
    ['', '-m'].forEach(suffix => {
      const badge = document.getElementById(`${step}-badge${suffix}`);
      const icon = document.getElementById(`${step}-icon${suffix}`);
      const button = document.getElementById(`${step}-button${suffix}`);
      const text = document.getElementById(`${step}-text${suffix}`);

      if (badge) badge.setAttribute('tone', enabled ? 'success' : config.tone);
      if (icon) icon.textContent = enabled ? '✓' : (step === 'step1' ? '1' : '2');
      if (button) button.setAttribute('variant', enabled ? 'tertiary' : 'primary');
      if (text) text.textContent = enabled ? `✓ ${config.text}` : (suffix ? 'Open' : (step === 'step1' ? 'Enable App Embed' : 'Add App Block'));
    });
  }

  function updateProgress() {
    const completed = [embedStatus, blockStatus].filter(Boolean).length;
    const progress = Math.round(completed / 2 * 100);

    const progressText = document.getElementById('progress-text');
    const progressBar = document.getElementById('progress-bar');

    if (progressText) progressText.textContent = `${completed}/2 steps completed`;
    if (progressBar) progressBar.setAttribute('progress', progress);
  }

  function updateBanner() {
    const banner = document.getElementById('status-banner');
    if (!banner) return;

    const isComplete = embedStatus;
    const messages = {
      complete: '🎉 Configuration Complete!|Your app is fully configured and ready to use.|success',
      needEmbed: 'Complete Setup|Enable the app embed to activate global functionality.|info'
    };

    const key = isComplete ? 'complete' : 'needEmbed';
    const [heading, message, tone] = messages[key].split('|');

    banner.innerHTML = `${message}`;
  }

  // Async function to check status with proper error handling
  async function checkStatus() {
    // Prevent concurrent requests
    if (isChecking) {
      return;
    }

    isChecking = true;

    try {
      const params = new URLSearchParams({
        isAjax: true,
        ajax1: true,
        shop1: '<%= params[:shop] %>',
        host: '<%= params[:host] %>',
        shop: '<%= params[:shop] %>',
        embedded: '<%= params[:embedded] %>'
      });

      const response = await fetch('/app_configured_or_not?' + params);
      const data = await response.json();


      if (data.success) {
        const newEmbed = data.appembedenabledornot || false;
        const newBlock = data.appblockexistsornot || false;

        // Handle embed status changes (enabled or disabled)
        if (newEmbed !== embedStatus) {
          const wasEnabled = embedStatus;
          embedStatus = newEmbed;
          updateStep('step1', newEmbed);

          if (typeof shopify !== 'undefined' && shopify.toast) {
            if (newEmbed) {
              shopify.toast.show('✅ App Embed enabled!');
            } else if (wasEnabled) {
              shopify.toast.show('⚠️ App Embed disabled!', { isError: true });
            }
          }
        }

        // Handle block status changes (added or removed)
        // if (newBlock !== blockStatus) {
        //   const wasEnabled = blockStatus;
        //   blockStatus = newBlock;
        //   updateStep('step2', newBlock);
        //   console.log(`✅ App Block status changed: ${wasEnabled} → ${newBlock}`);

        //   if (typeof shopify !== 'undefined' && shopify.toast) {
        //     if (newBlock) {
        //       shopify.toast.show('✅ App Block added!');
        //     } else if (wasEnabled) {
        //       shopify.toast.show('⚠️ App Block removed!', { isError: true });
        //     }
        //   }
        // }

        updateProgress();
        updateBanner();

        // Stop monitoring when app embed is configured
        if (embedStatus) {
          monitoringActive = false;
          stopActiveMonitoring();
          stopBackgroundMonitoring();
          // Only show toast if it hasn't been shown before (to avoid repeated messages)
          if (!completionToastShown && typeof shopify !== 'undefined' && shopify.toast) {
            completionToastShown = true;
            shopify.toast.show('🎉 Configuration completed!');
          }
        }
      }
    } catch (error) {
      console.error('❌ Status check failed:', error);
    } finally {
      isChecking = false;
      console.log('✓ Check complete');
    }
  }

  // Active monitoring - only when user opens editor (frequent checks)
  function startActiveMonitoring() {
    // Don't start if already configured
    if (embedStatus) {
      return;
    }

    stopActiveMonitoring();
    monitoringActive = true;

    // Immediate check
    checkStatus();

    // Check every 5 seconds when actively configuring
    activeInterval = setInterval(async () => {
      // Stop immediately if monitoring was deactivated
      if (!monitoringActive || !activeInterval) {
        stopActiveMonitoring();
        return;
      }

      // Stop if already configured before checking
      if (embedStatus) {
        monitoringActive = false;
        stopActiveMonitoring();
        return;
      }

      // Check status
      await checkStatus();

      // Stop if configured (check AFTER checkStatus completes and updates the status)
      if (!monitoringActive || embedStatus) {
        monitoringActive = false;
        stopActiveMonitoring();
        return;
      }
    }, 5000);

    // Auto-stop after 10 minutes of active monitoring
    setTimeout(() => {
      monitoringActive = false;
      stopActiveMonitoring();
    }, 600000);
  }

  function stopActiveMonitoring() {
    monitoringActive = false;
    if (activeInterval) {
      clearInterval(activeInterval);
      activeInterval = null;
    }
  }

  function stopBackgroundMonitoring() {
    if (backgroundTimeout) {
      clearTimeout(backgroundTimeout);
      backgroundTimeout = null;
    }
  }

  // Page visibility API - check when page becomes visible (user-initiated)
  function handleVisibilityChange() {
    if (!document.hidden) {
      // Only check if not already configured (to avoid unnecessary checks and repeated toasts)
      if (!embedStatus) {
        checkStatus();
      }
    }
  }

  // Window focus event - check when user returns to tab (user-initiated)
  function handleWindowFocus() {
    // Only check if not already configured (to avoid unnecessary checks and repeated toasts)
    if (!embedStatus) {
      checkStatus();
    }
  }

  // Verify buttons - manual check
  ['verify-btn', 'verify-btn-m'].forEach(id => {
    const btn = document.getElementById(id);
    const text = document.getElementById(id.replace('btn', 'text'));
    if (btn && text) {
      btn.addEventListener('click', async (e) => {
        e.preventDefault();
        btn.disabled = true;
        btn.loading = true;
        text.textContent = 'Verifying...';

        await checkStatus();

        setTimeout(() => {
          btn.disabled = false;
          btn.loading = false;
          text.textContent = id.includes('-m') ? 'Verify' : 'Verify Configuration';
        }, 1000);
      });
    }
  });

  // Callout dismissal
  if (localStorage.getItem('callout-dismissed') === 'true') {
    const callout = document.getElementById('callout-section');
    if (callout) callout.style.display = 'none';
  }

  // No automatic check on page load - status is already set from server-side variables
  // Status will only be checked when:
  // 1. User clicks verify button
  // 2. User opens editor (active monitoring)
  // 3. User returns to tab (focus/visibility events)

  // Listen for page visibility changes (when user switches back to tab)
  document.addEventListener('visibilitychange', handleVisibilityChange);

  // Listen for window focus (when user returns to tab)
  window.addEventListener('focus', handleWindowFocus);

  // Clean up when page unloads
  window.addEventListener('beforeunload', () => {
    stopActiveMonitoring();
    stopBackgroundMonitoring();
  });
});
function redirect_learn_more() {
  window.open("https://startbitsolutions.freshdesk.com/support/tickets/new", "_blank");
}
function redirect_settings() {
  location.replace("/settings?shop=<%= params[:shop] %>");
}

function redirect_home() {
  location.replace("/?shop=<%= params[:shop] %>&host=<%= params[:host] %>&embedded=1");
}
function redirect_options() {
  location.replace("/show_option_set?shop=<%= params[:shop] %>");
}

// Open app window for creating new option set
function openCreateModal() {
  const appWindow = document.getElementById('option-set-window');
  if (!appWindow) return;

  // Set src to the form page without ID (create mode)
  const formUrl = `/option_set_form?host=<%= params[:host] %>&shop=<%= params[:shop] %>&embedded=1`;
  appWindow.src = formUrl;
  appWindow.show();
}

// Set up app window event listeners for close and redirect
document.addEventListener('DOMContentLoaded', function () {
  const appWindow = document.getElementById('option-set-window');

  if (appWindow) {
    // Listen for hide event - redirect to show_option_set
    appWindow.addEventListener('hide', function () {
      setTimeout(() => {
        const redirectUrl = `/show_option_set?host=<%= params[:host] %>&shop=<%= params[:shop] %>&embedded=1`;
        window.location.href = redirectUrl;
      }, 200);
    });

    // Listen for messages from iframe
    window.addEventListener('message', function (event) {
      if (event.data?.type === 'CLOSE_APP_WINDOW') {
        if (appWindow.hide) {
          appWindow.hide().then(() => {
            // Redirect to show_option_set or specified URL
            const redirectUrl = event.data.redirectUrl || `/show_option_set?host=<%= params[:host] %>&shop=<%= params[:shop] %>&embedded=1`;
            setTimeout(() => {
              window.location.href = redirectUrl;
            }, 100);
          });
        }
      }
    });
  }
});
